package java.util.stream;
import java.util.function.IntConsumer;
public final class CharSequenceIntStream implements IntStream { private final CharSequence text;private final boolean codePoints; public CharSequenceIntStream(CharSequence text,boolean codePoints){this.text=text;this.codePoints=codePoints;} public void forEach(IntConsumer action){for(int i=0;i<text.length();i++){int c=text.charAt(i);if(codePoints&&Character.isHighSurrogate((char)c)&&i+1<text.length()&&Character.isLowSurrogate(text.charAt(i+1)))c=Character.toCodePoint((char)c,text.charAt(++i));action.accept(c);}} public int[] toArray(){int[] temp=new int[text.length()];int n=0;for(int i=0;i<text.length();i++){int c=text.charAt(i);if(codePoints&&Character.isHighSurrogate((char)c)&&i+1<text.length()&&Character.isLowSurrogate(text.charAt(i+1)))c=Character.toCodePoint((char)c,text.charAt(++i));temp[n++]=c;}int[] out=new int[n];System.arraycopy(temp,0,out,0,n);return out;} public long count(){return toArray().length;} public int sum(){int total=0;for(int n:toArray())total+=n;return total;} public void close(){} }
